const D = { energy: .55, scale: 1, density: .55, speed: 1, ruin: .45, hue: 30, x: .5, y: .44, style: 'roman', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// ---- A Roman tessellated floor, hand-set, running away to the vanishing point. The
// tesserae are laid in ANDAMENTO — flowing courses that follow the drawing rather than a
// grid — so the rows curve around a central emblema and run straight in the field, and each
// little stone sits at its own angle and catches the light on its own facet. Lacunae have
// opened where the floor failed and been patched with flat modern screed.
// ONLY BELOW THE HORIZON — above stays fully transparent so the bg slot shows through. ----

const cl = (v,a,b) => v<a?a:(v>b?b:v);
const u = Math.min(width, height), sd = P.seed|0;
function hsh(ix,iy){ let h=(Math.imul(ix,374761393)+Math.imul(iy,668265263)+Math.imul(sd,1442695041))|0;
  h=Math.imul(h^(h>>>13),1274126177)|0; return ((h^(h>>>16))>>>0)/4294967295; }   // >>> : a >> fold caps the hash at 0.5
function vn(x,y){ const ix=Math.floor(x), iy=Math.floor(y), fx=x-ix, fy=y-iy;
  const wx=fx*fx*(3-2*fx), wy=fy*fy*(3-2*fy);
  const a=hsh(ix,iy), b=hsh(ix+1,iy), c=hsh(ix,iy+1), d=hsh(ix+1,iy+1);
  return a+(b-a)*wx+(c-a)*wy+(a-b-c+d)*wx*wy; }
function fbm(x,y){ return .55*vn(x,y)+.28*vn(x*2.03+5.1,y*2.03-3.3)+.17*vn(x*4.07-2.7,y*4.07+7.9); }
function hsv(h,s,v){ h=(((h%360)+360)%360)/60; const c=v*s, xx=c*(1-Math.abs(h%2-1)), m=v-c;
  let r,g2,b2;
  if(h<1){r=c;g2=xx;b2=0}else if(h<2){r=xx;g2=c;b2=0}else if(h<3){r=0;g2=c;b2=xx}
  else if(h<4){r=0;g2=xx;b2=c}else if(h<5){r=xx;g2=0;b2=c}else{r=c;g2=0;b2=xx}
  return [(r+m)*255,(g2+m)*255,(b2+m)*255]; }

const sty = P.style, en = cl(P.energy,0,1), rn = cl(P.ruin,0,1);
const Hh = ((P.hue%360)+360)%360, tt = K.t;
const bp = sty==='blueprint', biz = sty==='byzantine', mono = sty==='monochrome', exc = sty==='excavation';

// ---- camera ----
const vy = cl(P.y,.18,.78)*height, vx = cl(P.x,.05,.95)*width;
const f = u*.92, H0 = 1;
const TS = .028*cl(P.scale,.35,2.4);         // tessera size in world units — fingernail-sized

// ---- perpetual scroll ----
if (S.z == null) S.z = 0;
if (S.pt == null || K.t < S.pt) S.pt = K.t;
const dt = cl(K.t - S.pt, 0, .1); S.pt = K.t;
S.z += dt * P.speed * (.12 + .17*K.intensity) * (.55 + .6*en);
const zoff = S.z;

const bass = (S.b = (S.b||0)*.82 + (A.bass||0)*.18);
// raking light drifting on incommensurate rates — every tessera facet flares as it passes
const l1x = 1.5*Math.sin(tt*.069) + .7*Math.sin(tt*.173+1.3);
const l1z = 3.2 + 1.9*Math.sin(tt*.049+.7) + .9*Math.sin(tt*.131+2.1);
const l2x = -1.8*Math.sin(tt*.097+2.2) - .6*Math.sin(tt*.229);
const l2z = 5.4 + 2.4*Math.sin(tt*.037+1.9) + 1.1*Math.sin(tt*.167+.4);
const glow = (.40+.60*en)*(.55+.5*K.intensity) + bass*.28;

// ---- palette: the tesserae are cut from a handful of real stones, so the whole floor is
// built from a tiny closed set of colours. That restraint is what makes it read antique. ----
function tessCol(pick, q){
  if (bp)   return [200+q*16, 40+q*30, 30+q*46];
  if (mono){ const v = pick<.34? 12+q*8 : pick<.62? 44+q*12 : pick<.86? 72+q*10 : 92+q*6;
             return [Hh+200, 3+q*4, v]; }
  if (biz){  // gold ground + jewel glass
    if (pick<.46) return [44, 62+q*22, 74+q*22];        // gold tesserae
    if (pick<.62) return [8, 72+q*16, 46+q*16];         // porphyry red
    if (pick<.78) return [214, 66+q*18, 40+q*18];       // lapis blue
    if (pick<.90) return [150, 48+q*20, 38+q*16];       // green glass
    return [Hh+30, 6+q*6, 88+q*10];                     // white marble
  }
  if (exc){  // a fresh dig: everything under a film of dust, colours only half revealed
    if (pick<.34) return [Hh+8, 14+q*10, 34+q*14];
    if (pick<.58) return [Hh+16, 10+q*8, 54+q*14];
    if (pick<.80) return [Hh+2, 20+q*12, 44+q*12];
    return [Hh+24, 6+q*5, 70+q*12];
  }
  // roman: bone white / ochre / terracotta / slate / near-black basalt
  if (pick<.36) return [Hh+18, 8+q*8,  72+q*16];        // bone
  if (pick<.58) return [Hh+2,  40+q*18, 56+q*16];       // ochre
  if (pick<.76) return [Hh-14, 52+q*18, 42+q*14];       // terracotta
  if (pick<.92) return [Hh+190, 12+q*10, 28+q*12];      // slate
  return [Hh+200, 8+q*6, 13+q*8];                       // basalt
}
const groutC = bp? [214,80,7] : exc? [Hh+14,12,22] : [Hh+16, 16, 20];
const cGr = hsv(groutC[0], groutC[1]/100, groutC[2]/100);
const screedC = exc? [Hh+10,6,44] : [Hh+8, 5, 38];
const cSc = hsv(screedC[0], screedC[1]/100, screedC[2]/100);

const BWb = 176, BHb = Math.max(44, Math.round(BWb*height/width));
if (!S.g || S.bk !== BWb+'x'+BHb){ if(S.g){ try{S.g.remove();}catch(e){} }
  S.g = createGraphics(BWb,BHb); S.g.pixelDensity(1); S.bk = BWb+'x'+BHb; }
const g = S.g; g.loadPixels(); const px = g.pixels;

const AL = P.alpha/100;
const j0 = Math.max(0, Math.floor((vy/height)*BHb));
for (let j=0;j<j0;j++) for (let i=0;i<BWb;i++) px[4*(j*BWb+i)+3] = 0;

// the emblema: the central panel the andamento flows around. Drifts very slowly with the
// scroll so a new panel arrives every so often.
const embZ = 3.4;

for (let j=j0;j<BHb;j++){
  const sy = (j+.5)/BHb*height, dy = sy - vy;
  if (dy < .35){ for (let i=0;i<BWb;i++) px[4*(j*BWb+i)+3] = 0; continue; }
  const Z = f*H0/dy, wz = Z + zoff;
  const far = cl((Z-1.1)/9, 0, 1);
  const det = cl(1 - far*1.05, .04, 1);
  for (let i=0;i<BWb;i++){
    const sx = (i+.5)/BWb*width, X = (sx-vx)*Z/f;
    const o = 4*(j*BWb+i);
    // ---- ANDAMENTO: courses that flow around the emblema instead of gridding the floor ----
    const ez = ((wz % (embZ*2)) + embZ*2) % (embZ*2) - embZ;   // z relative to nearest panel
    const er = Math.sqrt(X*X + ez*ez);
    const inEmb = er < .78;
    let cu, cv;                                   // coords along / across the courses
    if (inEmb){
      // inside the panel the rows run in concentric rings around the centre
      cu = Math.atan2(ez, X)*er/TS;
      cv = er/TS;
    } else {
      // in the field the rows run straight, but bend where they pass the panel
      const bend = Math.exp(-Math.max(0,er-.78)*1.6)*Math.atan2(ez, X)*.45;
      cu = (X/TS) + bend*3.0;
      cv = (wz/TS) + Math.sin(X*1.1)*.25;
    }
    const iu = Math.floor(cu), iv = Math.floor(cv);
    const fu = cu-iu, fv = cv-iv;
    const id = iu*719 + iv*37 + (inEmb?1013:0);
    const q = hsh(id, iv*53+iu);
    // ---- which stone is this tessera cut from? The drawing decides. ----
    // field = a ground with a geometric border; emblema = a figure in more colours
    let pick;
    if (inEmb){
      const fig = fbm(X*3.4+7.1, ez*3.4-2.3);
      pick = cl(fig*1.25 - .10 + (q-.5)*.10, 0, .999);
    } else {
      const bord = cl(1-Math.abs(er-.95)/.13, 0, 1);          // guilloche band around the panel
      const bq = .5+.5*Math.sin(Math.atan2(ez,X)*14 + er*8);
      const fieldPick = q*.42;                                // mostly ground stones
      pick = bord>.3 ? cl(.42+bq*.5,0,.999) : fieldPick;
    }
    const tc = tessCol(pick, q);
    let cr = hsv(tc[0], cl(tc[1],0,100)/100, cl(tc[2],0,100)/100);
    let r = cr[0], g2 = cr[1], b2 = cr[2];
    // ---- the individual stone: cut by hand, so it sits at its own angle on its own bed ----
    const jitU = (hsh(id*3+1, 7)-.5)*.22, jitV = (hsh(id*3+2, 11)-.5)*.22;
    const du = fu-.5-jitU, dv = fv-.5-jitV;
    const edge = .5 - Math.max(Math.abs(du), Math.abs(dv));
    const gw = .10 + rn*.07;
    const jt = cl(1 - edge/gw, 0, 1);             // the grout/mortar between stones
    // facet: each tessera is a chip with a slightly tilted top face
    const tiltU = (hsh(id*5+3, 13)-.5)*1.5, tiltV = (hsh(id*5+4, 17)-.5)*1.5;
    const toL1x = l1x - X, toL1z = l1z - (wz-zoff);
    const dl1 = Math.sqrt(toL1x*toL1x+toL1z*toL1z)+1e-3;
    const toL2x = l2x - X, toL2z = l2z - (wz-zoff);
    const dl2 = Math.sqrt(toL2x*toL2x+toL2z*toL2z)+1e-3;
    const pool = Math.exp(-dl1*dl1*.10) + Math.exp(-dl2*dl2*.07)*.72;
    const lamb = cl(.52 + (tiltU*(toL1x/dl1) + tiltV*(toL1z/dl1))*.42, 0, 1.4);
    // gold and glass tesserae are set deliberately askew so they flash — that is the point of them
    const flash = (biz && pick<.46) ? Math.pow(cl(lamb,0,1), 3.0)*pool*(.6+en*1.4) : 0;
    let sh = (.56 + lamb*.60) * (1 + pool*glow*.52) + flash*.9;
    // stone grain + a millennium of foot polish on the crowns
    const grain = fbm(cu*2.2+id*.3, cv*2.2)*det + (1-det)*.5;
    sh *= .86 + grain*.26;
    r *= sh; g2 *= sh; b2 *= sh;
    r += (cGr[0]-r)*jt*.80; g2 += (cGr[1]-g2)*jt*.80; b2 += (cGr[2]-b2)*jt*.80;
    // ---- lacunae: where the floor failed, and the flat modern screed patched into it ----
    const lac = cl((fbm(X*1.5+11.3, wz*1.5-3.7) - (1.02 - rn*.62))*7.0, 0, 1);
    if (lac > .001){
      const sg = fbm(X*9, wz*9)*.5+.5;
      const scr = [cSc[0]*(.8+sg*.4), cSc[1]*(.8+sg*.4), cSc[2]*(.8+sg*.4)];
      r += (scr[0]-r)*lac; g2 += (scr[1]-g2)*lac; b2 += (scr[2]-b2)*lac;
    }
    if (bp){
      const on = jt > .40 ? 1 : 0;
      const v2 = .12+.10*(1-far);
      r = on? 80 : v2*40; g2 = on? 200*det+36 : v2*100; b2 = on? 248 : v2*172;
    }
    const hazeK = far*far*.85;
    const hc = bp? [40,120,190] : [140*.72, 132*.72, 118*.78];
    r += (hc[0]-r)*hazeK; g2 += (hc[1]-g2)*hazeK; b2 += (hc[2]-b2)*hazeK;
    px[o]=cl(r,0,255); px[o+1]=cl(g2,0,255); px[o+2]=cl(b2,0,255);
    px[o+3] = 255*AL*cl(1-far*far*.72, 0, 1)*cl(dy/2.2, 0, 1);
  }
}
g.updatePixels();
push();
image(g,0,0,width,height);
pop();

// ---- dust drifting low over the floor, catching the raking light ----
push();
blendMode(ADD);
noStroke();
const dens = cl(P.density,0,1);
const NM = Math.round(6 + dens*44);
for (let i=0;i<NM;i++){
  const f1 = hsh(i*19+7, 3), f2 = hsh(i*19+8, 5), f3 = hsh(i*19+9, 11);
  const mz = ((f2 + tt*(.012+f3*.05)*P.speed) % 1.05);
  const my = vy + Math.pow(mz,2.0)*(height-vy)*1.0;
  const mx = (f1 + Math.sin(tt*(.15+f3*.35)+f1*6.28)*.045
                 + Math.sin(tt*(.06+f2*.13))*.03)*width;
  const sz = u*(.0014+f3*.0044)*(.4+mz*1.7);
  fill(biz?44:Hh+18, bp?40:12, 100, (6+f3*12)*(.3+en)*AL*(1-mz*.35));
  ellipse(mx, my, sz, sz*.8);
}
blendMode(BLEND);
pop();

blendMode(BLEND);
drawingContext.shadowBlur = 0;
drawingContext.globalAlpha = 1;
